fn lifecycle_dispatch(
    args: &LifecycleArgs,
    explicit_host: Option<&str>,
) -> Result<DispatchOutcome> {
    let Some(host) = resolve_host_config(explicit_host)? else {
        return Ok(missing_host_dispatch(
            "lifecycle",
            serde_json::to_value(args)?,
            vec![
                format!(
                    "fwc lifecycle {} --valid-actions --host <endpoint>",
                    args.connector
                ),
                "Set `FWC_HOST` or `FCP_HOST_ENDPOINT`, or configure an active FCP context."
                    .to_owned(),
            ],
        ));
    };
    let client = HostAdminClient::new(&host.endpoint)?;
    let (catalog, _) = client.catalog(None)?;
    let connector = match catalog.resolve_connector(&args.connector) {
        Ok(c) => c,
        Err(error) => {
            return Ok(connector_resolution_dispatch(
                "lifecycle",
                &args.connector,
                &error,
            ));
        }
    };

    // Determine current lifecycle state from catalog health
    let current_state = lifecycle_state_from_catalog(connector);

    // --valid-actions: show valid lifecycle actions for the current state
    if args.valid_actions {
        let valid = lifecycle_mutations::valid_actions(current_state);
        let valid_labels: Vec<&str> = valid.iter().map(|a| a.label()).collect();
        let evidence_handles = lifecycle_evidence_handles(
            connector.summary.id.as_str(),
            &host.endpoint,
            current_state,
            &valid,
        );
        let toon = format!(
            "Lifecycle: {}\n  State: {}\n  Valid actions: {}",
            connector.slug,
            current_state.label(),
            if valid_labels.is_empty() {
                "none".to_owned()
            } else {
                valid_labels.join(", ")
            },
        );
        let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "lifecycle");
        let mut payload = json!({
            "status": "ok",
            "command": "lifecycle",
            "mode": "valid-actions",
            "connector": {
                "slug": &connector.slug,
                "canonical_id": connector.summary.id.as_str(),
            },
            "current_state": current_state.label(),
            "valid_actions": valid_labels,
            "toon": toon,
            "next_actions": valid.iter().map(|a| {
                format!("fwc lifecycle {} --action {} --preflight --host {}", connector.slug, a.label(), host.endpoint)
            }).collect::<Vec<_>>(),
        });
        attach_install_contract(
            &mut payload,
            "lifecycle",
            "host-admin-api",
            "node-local-root-app",
            "lifecycle-valid-actions",
            Some(&host.endpoint),
            false,
            false,
            false,
            "Live lifecycle planning answers are authoritative for the current node's connector summary and policy surface, but they do not mutate state or prove post-change runtime convergence.",
            evidence_handles,
        );
        envelope.inject_into(&mut payload);
        return Ok(DispatchOutcome {
            payload,
            exit_code: CliExitCode::Success,
        });
    }

    // --preflight: run a preflight safety check for the specified action
    if args.preflight {
        let Some(ref action_str) = args.action else {
            return Ok(DispatchOutcome {
                payload: json!({
                    "status": "error",
                    "command": "lifecycle",
                    "error": {
                        "type": "missing-action",
                        "message": "--preflight requires --action <action>",
                        "recoverable": true,
                    },
                    "next_actions": [
                        format!("fwc lifecycle {} --valid-actions --host {}", args.connector, host.endpoint),
                    ],
                }),
                exit_code: CliExitCode::Validation,
            });
        };
        let action = match parse_lifecycle_action(action_str) {
            Some(a) => a,
            None => {
                return Ok(DispatchOutcome {
                    payload: json!({
                        "status": "error",
                        "command": "lifecycle",
                        "error": {
                            "type": "invalid-action",
                            "message": format!("Unknown lifecycle action: `{action_str}`. Valid: enable, disable, start, stop, restart, force-stop."),
                            "recoverable": true,
                        },
                        "next_actions": [
                            format!("fwc lifecycle {} --valid-actions --host {}", args.connector, host.endpoint),
                        ],
                    }),
                    exit_code: CliExitCode::Validation,
                });
            }
        };

        let request =
            lifecycle_mutations::MutationRequest::new(connector.summary.id.to_string(), action)
                .with_force(args.force)
                .with_dry_run(args.dry_run);
        let check = lifecycle_mutations::preflight(&request, current_state);
        let mut evidence_handles = lifecycle_evidence_handles(
            connector.summary.id.as_str(),
            &host.endpoint,
            current_state,
            &[action],
        );
        evidence_handles.push(json!({
            "kind": "lifecycle-preflight",
            "connector_id": connector.summary.id.as_str(),
            "endpoint": &host.endpoint,
            "action": action.label(),
            "risk_level": check.risk_level.label(),
            "requires_confirmation": check.requires_confirmation,
            "is_noop": check.is_noop,
            "can_proceed": check.can_proceed(),
        }));
        let toon = lifecycle_mutations::format_preflight_toon(&check);

        let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "lifecycle");
        let mut payload = json!({
            "status": "ok",
            "command": "lifecycle",
            "mode": "preflight",
            "connector": {
                "slug": &connector.slug,
                "canonical_id": connector.summary.id.as_str(),
            },
            "current_state": current_state.label(),
            "action": action.label(),
            "preflight": {
                "risk_level": check.risk_level.label(),
                "requires_confirmation": check.requires_confirmation,
                "is_noop": check.is_noop,
                "can_proceed": check.can_proceed(),
                "estimated_duration_ms": check.estimated_duration.as_millis(),
                "warnings": check.warnings,
                "blockers": check.blockers,
            },
            "toon": toon,
            "next_actions": if check.can_proceed() {
                vec![
                    format!("fwc lifecycle {} --action {} --host {}", connector.slug, action.label(), host.endpoint),
                ]
            } else {
                vec![
                    format!("fwc lifecycle {} --valid-actions --host {}", connector.slug, host.endpoint),
                ]
            },
        });
        attach_install_contract(
            &mut payload,
            "lifecycle",
            "host-admin-api",
            "node-local-root-app",
            "lifecycle-preflight",
            Some(&host.endpoint),
            false,
            false,
            false,
            "Live lifecycle preflight answers are authoritative for the current node's planning state and safety checks, but they do not execute the requested lifecycle change.",
            evidence_handles,
        );
        envelope.inject_into(&mut payload);
        return Ok(DispatchOutcome {
            payload,
            exit_code: CliExitCode::Success,
        });
    }

    // Default: show current lifecycle state summary
    let valid = lifecycle_mutations::valid_actions(current_state);
    let valid_labels: Vec<&str> = valid.iter().map(|a| a.label()).collect();
    let evidence_handles = lifecycle_evidence_handles(
        connector.summary.id.as_str(),
        &host.endpoint,
        current_state,
        &valid,
    );
    let toon = format!(
        "Lifecycle: {}\n  State: {}\n  Valid actions: {}",
        connector.slug,
        current_state.label(),
        if valid_labels.is_empty() {
            "none".to_owned()
        } else {
            valid_labels.join(", ")
        },
    );
    let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "lifecycle");
    let mut payload = json!({
        "status": "ok",
        "command": "lifecycle",
        "connector": {
            "slug": &connector.slug,
            "canonical_id": connector.summary.id.as_str(),
        },
        "current_state": current_state.label(),
        "valid_actions": valid_labels,
        "toon": toon,
        "next_actions": [
            format!("fwc lifecycle {} --valid-actions --host {}", connector.slug, host.endpoint),
            format!("fwc lifecycle {} --action start --preflight --host {}", connector.slug, host.endpoint),
        ],
    });
    attach_install_contract(
        &mut payload,
        "lifecycle",
        "host-admin-api",
        "node-local-root-app",
        "lifecycle-summary",
        Some(&host.endpoint),
        false,
        false,
        false,
        "Live lifecycle summary answers are authoritative for the current node's connector lifecycle state, but they do not execute any lifecycle transition.",
        evidence_handles,
    );
    envelope.inject_into(&mut payload);
    Ok(DispatchOutcome {
        payload,
        exit_code: CliExitCode::Success,
    })
}

/// Map catalog connector status to lifecycle_mutations::LifecycleState.
fn lifecycle_state_from_catalog(
    connector: &HostConnectorRecord,
) -> lifecycle_mutations::LifecycleState {
    if !connector.summary.enabled {
        return lifecycle_mutations::LifecycleState::Disabled;
    }
    if connector.summary.health.is_healthy() {
        lifecycle_mutations::LifecycleState::Running
    } else if connector.summary.health.is_available() {
        lifecycle_mutations::LifecycleState::Running // degraded but running
    } else {
        lifecycle_mutations::LifecycleState::Failed
    }
}

/// Parse a lifecycle action string to the enum variant.
fn parse_lifecycle_action(s: &str) -> Option<lifecycle_mutations::LifecycleAction> {
    match s {
        "enable" => Some(lifecycle_mutations::LifecycleAction::Enable),
        "disable" => Some(lifecycle_mutations::LifecycleAction::Disable),
        "start" => Some(lifecycle_mutations::LifecycleAction::Start),
        "stop" => Some(lifecycle_mutations::LifecycleAction::Stop),
        "restart" => Some(lifecycle_mutations::LifecycleAction::Restart),
        "force-stop" | "force_stop" => Some(lifecycle_mutations::LifecycleAction::ForceStop),
        _ => None,
    }
}

fn rollout_dispatch(args: &RolloutArgs, explicit_host: Option<&str>) -> Result<DispatchOutcome> {
    let command = match &args.command {
        RolloutCommand::Set(_) => "rollout set",
        RolloutCommand::Status(_) => "rollout status",
        RolloutCommand::Rollback(_) => "rollout rollback",
    };

    let Some(host) = resolve_host_config(explicit_host)? else {
        return Ok(missing_host_dispatch(
            command,
            serde_json::to_value(args)?,
            vec![
                format!("fwc {command} <connector> --host <endpoint>"),
                "Set `FWC_HOST` or `FCP_HOST_ENDPOINT`, or configure an active FCP context."
                    .to_owned(),
            ],
        ));
    };

    let client = HostAdminClient::new(&host.endpoint)?;
    let (catalog, _) = client.catalog(None)?;

    match &args.command {
        RolloutCommand::Set(set_args) => {
            if set_args.canary > 100 {
                anyhow::bail!("canary percentage must be 0-100, got {}", set_args.canary);
            }
            let connector = match catalog.resolve_connector(&set_args.connector) {
                Ok(connector) => connector,
                Err(error) => {
                    return Ok(connector_resolution_dispatch(
                        "rollout set",
                        &set_args.connector,
                        &error,
                    ));
                }
            };
            let pin_state = client.pin_status(connector.summary.id.as_str())?;
            let version = pin_state.version.clone().ok_or_else(|| {
                anyhow::anyhow!(
                    "no pinned version is configured for `{}`. Pin a version first with `fwc pin {} --to <version>`.",
                    connector.slug,
                    connector.slug
                )
            })?;
            let previous_version = Some(
                client
                    .rollout_status(connector.summary.id.as_str())?
                    .status
                    .version,
            );
            let policy = RolloutPolicy::builder()
                .canary_percent(set_args.canary)
                .build();
            policy.validate()?;
            let schedule = HostRolloutScheduleRequest {
                connector_id: connector.summary.id.to_string(),
                version,
                previous_version,
                policy,
            };
            let outcome = client.schedule_rollout(&schedule)?;
            let evidence_handles = rollout_set_evidence_handles(
                connector.summary.id.as_str(),
                &host.endpoint,
                set_args.canary,
                &pin_state,
                &outcome,
            );

            let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "rollout");
            let mut payload = json!({
                "status": "ok",
                "command": "rollout",
                "subcommand": "set",
                "source": "host-admin-api",
                "message": format!(
                    "Scheduled a {}% canary rollout for `{}`.",
                    set_args.canary,
                    connector.slug
                ),
                "connector": {
                    "slug": &connector.slug,
                    "canonical_id": connector.summary.id.as_str(),
                },
                "requested_canary_percent": set_args.canary,
                "pin": pin_state,
                "rollout": outcome,
                "next_actions": [
                    format!("fwc rollout status {} --host {}", connector.slug, host.endpoint),
                    format!("fwc status {} --host {}", connector.slug, host.endpoint),
                ],
            });
            attach_install_contract(
                &mut payload,
                "rollout",
                "host-admin-api",
                "node-local-root-app",
                "rollout-set",
                Some(&host.endpoint),
                true,
                false,
                false,
                "Live rollout scheduling answers are authoritative for the current node's rollout policy mutation, but they do not by themselves prove later canary convergence.",
                evidence_handles,
            );
            envelope.inject_into(&mut payload);
            Ok(DispatchOutcome {
                payload,
                exit_code: CliExitCode::Success,
            })
        }
        RolloutCommand::Status(status_args) => {
            let connector = match catalog.resolve_connector(&status_args.connector) {
                Ok(connector) => connector,
                Err(error) => {
                    return Ok(connector_resolution_dispatch(
                        "rollout status",
                        &status_args.connector,
                        &error,
                    ));
                }
            };
            let pin = client.pin_status(connector.summary.id.as_str())?;
            let rollout = client.rollout_status(connector.summary.id.as_str())?;
            let evidence_handles = rollout_status_evidence_handles(
                connector.summary.id.as_str(),
                &host.endpoint,
                &pin,
                &rollout,
            );

            let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "rollout");
            let mut payload = json!({
                "status": "ok",
                "command": "rollout",
                "subcommand": "status",
                "source": "host-admin-api",
                "message": format!("Loaded live rollout state for `{}`.", connector.slug),
                "connector": {
                    "slug": &connector.slug,
                    "canonical_id": connector.summary.id.as_str(),
                },
                "pin": pin,
                "rollout": rollout,
                "next_actions": [
                    format!("fwc status {} --host {}", connector.slug, host.endpoint),
                    format!("fwc rollout rollback {} --to <version> --host {}", connector.slug, host.endpoint),
                ],
            });
            attach_install_contract(
                &mut payload,
                "rollout",
                "host-admin-api",
                "node-local-root-app",
                "rollout-status",
                Some(&host.endpoint),
                false,
                false,
                false,
                "Live rollout status answers are authoritative for the current node's rollout state snapshot, but they do not mutate rollout policy or prove future promotion outcomes.",
                evidence_handles,
            );
            envelope.inject_into(&mut payload);
            Ok(DispatchOutcome {
                payload,
                exit_code: CliExitCode::Success,
            })
        }
        RolloutCommand::Rollback(rollback_args) => {
            let connector = match catalog.resolve_connector(&rollback_args.connector) {
                Ok(connector) => connector,
                Err(error) => {
                    return Ok(connector_resolution_dispatch(
                        "rollout rollback",
                        &rollback_args.connector,
                        &error,
                    ));
                }
            };
            let version = rollback_args.to.parse::<semver::Version>().map_err(|error| {
                anyhow::anyhow!(
                    "`fwc rollout rollback` requires an explicit semantic version target: {error}"
                )
            })?;
            let response = client.rollback(connector.summary.id.as_str(), &version)?;
            let evidence_handles = rollout_rollback_evidence_handles(
                connector.summary.id.as_str(),
                &host.endpoint,
                &response,
            );

            let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "rollout");
            let mut payload = json!({
                "status": "ok",
                "command": "rollout",
                "subcommand": "rollback",
                "source": "host-admin-api",
                "message": format!(
                    "Rolled `{}` from `{}` back to `{}`.",
                    connector.slug, response.from_version, response.to_version
                ),
                "connector": {
                    "slug": &connector.slug,
                    "canonical_id": connector.summary.id.as_str(),
                },
                "rollback": response,
                "next_actions": [
                    format!("fwc rollout status {} --host {}", connector.slug, host.endpoint),
                    format!("fwc status {} --host {}", connector.slug, host.endpoint),
                ],
            });
            attach_install_contract(
                &mut payload,
                "rollout",
                "host-admin-api",
                "node-local-root-app",
                "rollout-rollback",
                Some(&host.endpoint),
                true,
                false,
                false,
                "Live rollout rollback answers are authoritative for the current node's rollback mutation, but they do not by themselves prove post-rollback runtime stabilization.",
                evidence_handles,
            );
            envelope.inject_into(&mut payload);
            Ok(DispatchOutcome {
                payload,
                exit_code: CliExitCode::Success,
            })
        }
    }
}

fn auth_dispatch(args: &AuthArgs, explicit_host: Option<&str>) -> Result<DispatchOutcome> {
    let store = CredentialStore::default_path();
    auth_dispatch_with_store_and_host(args, &store, explicit_host)
}

#[cfg(test)]
fn auth_dispatch_with_store(args: &AuthArgs, store: &CredentialStore) -> Result<DispatchOutcome> {
    auth_dispatch_with_store_and_host(args, store, None)
}

fn auth_dispatch_with_store_and_host(
    args: &AuthArgs,
    store: &CredentialStore,
    explicit_host: Option<&str>,
) -> Result<DispatchOutcome> {
    match &args.command {
        AuthCommand::Add(add_args) => auth_add_dispatch(add_args, store),
        AuthCommand::Login(login_args) => auth_login_dispatch(login_args, explicit_host),
        AuthCommand::LoginPoll(poll_args) => auth_login_poll_dispatch(poll_args, explicit_host),
        AuthCommand::LoginComplete(complete_args) => {
            auth_login_complete_dispatch(complete_args, explicit_host)
        }
        AuthCommand::List(list_args) => auth_list_dispatch(list_args, store, explicit_host),
        AuthCommand::Profiles(profiles_args) => {
            auth_profiles_dispatch(profiles_args, explicit_host)
        }
        AuthCommand::SetPriority(priority_args) => {
            auth_set_priority_dispatch(priority_args, explicit_host)
        }
        AuthCommand::Show(target) => auth_show_dispatch(target, store, explicit_host),
        AuthCommand::Remove(target) => auth_remove_dispatch(target, store),
        AuthCommand::RemoveProfile(remove_args) => {
            auth_remove_profile_dispatch(remove_args, explicit_host)
        }
        AuthCommand::Refresh(refresh_args) => auth_refresh_dispatch(refresh_args, explicit_host),
        AuthCommand::MigrateFromClaudeCode(migrate_args) => {
            auth_migrate_from_claude_code_dispatch(migrate_args, explicit_host)
        }
        AuthCommand::Test(target) => auth_test_dispatch(target, store),
        AuthCommand::Verify(target) => auth_verify_dispatch(target, store),
        AuthCommand::Status(status_args) => auth_status_dispatch(status_args, store),
    }
}

fn auth_host_config(
    subcommand: &str,
    details: Value,
    next_actions: Vec<String>,
    explicit_host: Option<&str>,
) -> Result<ResolvedHostConfig, DispatchOutcome> {
    match resolve_host_config(explicit_host) {
        Ok(Some(host)) => Ok(host),
        Ok(None) => Err(missing_host_dispatch(
            "auth",
            json!({
                "subcommand": subcommand,
                "request": details,
            }),
            next_actions,
        )),
        Err(error) => Err(DispatchOutcome {
            payload: json!({
                "status": "error",
                "command": "auth",
                "subcommand": subcommand,
                "error": {
                    "type": "host-context-error",
                    "message": error.to_string(),
                    "recoverable": true,
                },
                "next_actions": [
                    "Retry with `--host <endpoint>`.".to_owned(),
                    "Run `fwc context list` to inspect configured host contexts.".to_owned(),
                ],
            }),
            exit_code: CliExitCode::Transport,
        }),
    }
}

fn auth_profile_evidence_handles(
    provider: &str,
    profile_id: Option<&str>,
    endpoint: &str,
    action: &str,
) -> Vec<Value> {
    vec![json!({
        "kind": "provider-auth-profile-admin",
        "provider": provider,
        "profile_id": profile_id,
        "endpoint": endpoint,
        "action": action,
    })]
}

fn attach_auth_host_contract(
    payload: &mut Value,
    endpoint: &str,
    provider: &str,
    profile_id: Option<&str>,
    action: &str,
    mutated: bool,
) {
    attach_install_contract(
        payload,
        "auth",
        "host-admin-api",
        "node-local-root-app",
        action,
        Some(endpoint),
        mutated,
        false,
        false,
        "Live provider-auth profile answers are authoritative for the current fcp-host process and are redaction-safe, but they do not by themselves prove external provider login success.",
        auth_profile_evidence_handles(provider, profile_id, endpoint, action),
    );
}

fn auth_login_validation_error(
    args: &AuthLoginArgs,
    message: impl Into<String>,
) -> DispatchOutcome {
    DispatchOutcome {
        payload: json!({
            "status": "error",
            "command": "auth",
            "subcommand": "login",
            "provider": args.provider,
            "profile_id": args.profile,
            "error": {
                "type": "invalid-auth-login-request",
                "message": message.into(),
                "recoverable": true,
            },
            "next_actions": [
                format!("fwc auth login {} --profile {} --api-key <secret> --host <endpoint>", args.provider, args.profile),
                format!("fwc auth login {} --profile {} --oauth-device --client-id <id> --device-code-url <url> --token-url <url> --scope <scope> --host <endpoint>", args.provider, args.profile),
                format!("fwc auth login {} --profile {} --oauth-auth-code --client-id <id> --authorize-url <url> --token-url <url> --redirect-uri <url> --scope <scope> --host <endpoint>", args.provider, args.profile),
            ],
        }),
        exit_code: CliExitCode::Validation,
    }
}

fn require_auth_login_field(
    args: &AuthLoginArgs,
    field_name: &'static str,
    value: Option<&String>,
) -> Result<String, DispatchOutcome> {
    value
        .cloned()
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            auth_login_validation_error(
                args,
                format!(
                    "`--{}` is required for this login method.",
                    field_name.replace('_', "-")
                ),
            )
        })
}

fn auth_login_request(args: &AuthLoginArgs) -> Result<(Value, &'static str), DispatchOutcome> {
    let method_count = usize::from(args.api_key.is_some())
        + usize::from(args.oauth_device)
        + usize::from(args.oauth_auth_code);
    if method_count != 1 {
        return Err(auth_login_validation_error(
            args,
            "Choose exactly one login method: `--api-key`, `--oauth-device`, or `--oauth-auth-code`.",
        ));
    }

    let label = args.label.clone().unwrap_or_else(|| args.profile.clone());
    if let Some(api_key) = args.api_key.as_ref() {
        let mut request = json!({
            "profile_id": args.profile,
            "method": "api_key",
            "label": label,
            "priority": args.priority,
            "api_key": api_key,
        });
        if let Some(header_name) = args.header_name.as_deref() {
            request["header_name"] = json!(header_name);
        }
        if let Some(value_prefix) = args.value_prefix.as_deref() {
            request["value_prefix"] = json!(value_prefix);
        }
        return Ok((request, "api_key"));
    }

    if args.header_name.is_some() || args.value_prefix.is_some() {
        return Err(auth_login_validation_error(
            args,
            "`--header-name` and `--value-prefix` only apply to `--api-key` login.",
        ));
    }

    if args.oauth_device {
        let request = json!({
            "profile_id": args.profile,
            "method": "oauth_device",
            "label": label,
            "priority": args.priority,
            "client_id": require_auth_login_field(args, "client_id", args.client_id.as_ref())?,
            "device_code_url": require_auth_login_field(args, "device_code_url", args.device_code_url.as_ref())?,
            "token_url": require_auth_login_field(args, "token_url", args.token_url.as_ref())?,
            "scope": args.scope,
        });
        return Ok((request, "oauth_device"));
    }

    let request = json!({
        "profile_id": args.profile,
        "method": "oauth_auth_code",
        "label": label,
        "priority": args.priority,
        "client_id": require_auth_login_field(args, "client_id", args.client_id.as_ref())?,
        "client_secret": args.client_secret,
        "authorize_url": require_auth_login_field(args, "authorize_url", args.authorize_url.as_ref())?,
        "token_url": require_auth_login_field(args, "token_url", args.token_url.as_ref())?,
        "redirect_uri": require_auth_login_field(args, "redirect_uri", args.redirect_uri.as_ref())?,
        "scope": args.scope,
        "use_pkce": !args.no_pkce,
    });
    Ok((request, "oauth_auth_code"))
}

fn auth_login_dispatch(
    args: &AuthLoginArgs,
    explicit_host: Option<&str>,
) -> Result<DispatchOutcome> {
    let (request, method) = match auth_login_request(args) {
        Ok(request) => request,
        Err(outcome) => return Ok(outcome),
    };
    let host = match auth_host_config(
        "login",
        serde_json::to_value(args)?,
        vec![
            format!(
                "fwc auth login {} --profile {} --api-key <secret> --host <endpoint>",
                args.provider, args.profile
            ),
            "Set `FWC_HOST` or `FCP_HOST_ENDPOINT`, or configure an active FCP context.".to_owned(),
        ],
        explicit_host,
    ) {
        Ok(host) => host,
        Err(outcome) => return Ok(outcome),
    };
    let client = HostAdminClient::new(&host.endpoint)?;
    let response = client.auth_profile_upsert(&args.provider, &request)?;
    let oauth_start = match method {
        "oauth_device" => Some(client.auth_oauth_device_start(&args.provider, &args.profile)?),
        "oauth_auth_code" => {
            Some(client.auth_oauth_auth_code_start(&args.provider, &args.profile)?)
        }
        _ => None,
    };
    let envelope = CommandEnvelope::new(CommandAvailability::LiveRuntime, "auth");
    let mut next_actions = vec![format!(
        "fwc auth profiles {} --profile {} --host {}",
        args.provider, args.profile, host.endpoint
    )];
    if let Some(start) = oauth_start.as_ref() {
        let login_id = start["login_id"].as_str().unwrap_or("<login-id>");
        if method == "oauth_device" {
            next_actions.push(format!(
                "fwc auth login-poll {} --profile {} --login-id {} --host {}",
                args.provider, args.profile, login_id, host.endpoint
            ));
        } else {
            next_actions.push(format!(
                "fwc auth login-complete {} --profile {} --login-id {} --code <code> --state <state> --host {}",
                args.provider, args.profile, login_id, host.endpoint
            ));
        }
    } else {
        next_actions.push(format!(
            "fwc auth refresh {} --profile {} --host {}",
            args.provider, args.profile, host.endpoint
        ));
    }
    let mut payload = json!({
        "status": "ok",
        "command": "auth",
        "subcommand": "login",
        "source": "host-admin-api",
        "message": format!("Stored host-managed provider auth profile `{}` for `{}`.", args.profile, args.provider),
        "provider": args.provider,
        "profile_id": args.profile,
        "method": method,
        "profile": response["profile"].clone(),
        "oauth_start": oauth_start,
        "next_actions": next_actions,
    });
    attach_auth_host_contract(
        &mut payload,
        &host.endpoint,
        &args.provider,
        Some(&args.profile),
        "provider-auth-profile-upsert",
        true,
    );
    envelope.inject_into(&mut payload);
    Ok(DispatchOutcome {
        payload,
        exit_code: CliExitCode::Success,
    })
}

