    fn assert_install_contract(
        payload: &Value,
        source: &str,
        transport: &str,
        scope: &str,
        live_host_mutated: bool,
        degraded: bool,
        fallback_derived: bool,
    ) {
        assert_eq!(payload["provenance"]["source"], source);
        assert_eq!(payload["provenance"]["transport"], transport);
        assert_eq!(payload["provenance"]["scope"], scope);
        assert_eq!(payload["provenance"]["authoritative"], true);
        assert_eq!(payload["provenance"]["mesh_backed"], false);
        assert_eq!(
            payload["provenance"]["live_host_mutated"],
            live_host_mutated
        );
        assert_eq!(payload["provenance"]["degraded"], degraded);
        assert_eq!(payload["provenance"]["fallback_derived"], fallback_derived);
        assert_eq!(payload["provenance"]["command"], payload["command"]);
        assert!(
            payload["provenance"]["caveat"]
                .as_str()
                .is_some_and(|caveat| !caveat.is_empty())
        );
        if source == "host-admin-api" {
            assert!(
                payload["provenance"]["endpoint"]
                    .as_str()
                    .is_some_and(|endpoint| !endpoint.is_empty())
            );
        } else {
            assert!(payload["provenance"]["endpoint"].is_null());
        }
    }

    fn assert_live_truth_resolution(
        payload: &Value,
        knowledge_state: &str,
        resolver_branch: &str,
        authoritative_scope: &str,
        mesh_backed: bool,
        degraded: bool,
        fallback_derived: bool,
    ) {
        assert_eq!(payload["resolution"]["knowledge_state"], knowledge_state);
        assert_eq!(payload["resolution"]["resolver_branch"], resolver_branch);
        assert_eq!(
            payload["resolution"]["authoritative_scope"],
            authoritative_scope
        );
        assert_eq!(payload["resolution"]["mesh_backed"], mesh_backed);
        assert_eq!(payload["resolution"]["degraded"], degraded);
        assert_eq!(payload["resolution"]["fallback_derived"], fallback_derived);
        assert!(
            payload["resolution"]["reason"]
                .as_str()
                .is_some_and(|reason| !reason.is_empty())
        );
    }

    fn assert_tool_inventory_provenance(
        payload: &Value,
        source: &str,
        availability: &str,
        authoritative: bool,
        mode: &str,
        surface_state: &str,
    ) {
        assert_eq!(payload["mode"], mode);
        assert_eq!(payload["surface_state"], surface_state);
        assert_eq!(payload["provenance"]["source"], source);
        assert_eq!(payload["provenance"]["availability"], availability);
        assert_eq!(payload["provenance"]["authoritative"], authoritative);
        assert_eq!(payload["provenance"]["command"], payload["command"]);
        assert!(
            payload["provenance"]["caveat"]
                .as_str()
                .is_some_and(|caveat| !caveat.is_empty())
        );
        assert!(
            payload["tool_provenance"]
                .as_array()
                .is_some_and(|entries| !entries.is_empty())
        );
    }

    fn spawn_mock_host(
        routes: StdBTreeMap<String, Value>,
        expected_requests: usize,
    ) -> (String, thread::JoinHandle<()>) {
        let listener = TcpListener::bind("127.0.0.1:0").expect("mock host should bind");
        listener
            .set_nonblocking(true)
            .expect("mock host should configure nonblocking accept");
        let endpoint = format!(
            "http://{}",
            listener.local_addr().expect("mock host address")
        );
        let responses = routes
            .into_iter()
            .map(|(key, value)| {
                (
                    key,
                    serde_json::to_string(&value).expect("mock response should serialize"),
                )
            })
            .collect::<StdBTreeMap<_, _>>();

        let handle = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(5);
            let mut served = 0usize;

            while served < expected_requests && Instant::now() < deadline {
                let (mut stream, _) = match listener.accept() {
                    Ok(connection) => connection,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                        continue;
                    }
                    Err(error) => panic!("mock host accept failed: {error}"),
                };

                served += 1;
                stream
                    .set_nonblocking(false)
                    .expect("mock host stream should switch back to blocking mode");

                let mut reader =
                    BufReader::new(stream.try_clone().expect("mock host should clone socket"));
                let mut request_line = String::new();
                reader
                    .read_line(&mut request_line)
                    .expect("mock host should read request line");
                assert!(
                    !request_line.trim().is_empty(),
                    "mock host received an empty request line"
                );

                let mut content_length = 0usize;
                loop {
                    let mut header = String::new();
                    reader
                        .read_line(&mut header)
                        .expect("mock host should read headers");
                    if header == "\r\n" || header.is_empty() {
                        break;
                    }
                    if let Some((name, value)) = header.split_once(':')
                        && name.eq_ignore_ascii_case("content-length")
                    {
                        content_length = value
                            .trim()
                            .parse()
                            .expect("content-length should be numeric");
                    }
                }

                if content_length > 0 {
                    let mut body = vec![0u8; content_length];
                    reader
                        .read_exact(&mut body)
                        .expect("mock host should read request body");
                }

                let mut parts = request_line.split_whitespace();
                let method = parts.next().expect("request method should exist");
                let path = parts.next().expect("request path should exist");
                let key = format!("{method} {path}");
                let body = responses.get(&key).unwrap_or_else(|| {
                    panic!(
                        "unexpected mock host request `{key}`; expected one of {:?}",
                        responses.keys().collect::<Vec<_>>()
                    )
                });

                write!(
                    stream,
                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{}",
                    body.len(),
                    body
                )
                .expect("mock host should write response");
                stream.flush().expect("mock host should flush response");
            }

            assert_eq!(
                served, expected_requests,
                "mock host served {served} request(s), expected {expected_requests}"
            );
        });

        (endpoint, handle)
    }

