    #[test]
    fn doctor_migration_probe_warning_thresholds_classify_anomalies() {
        use fcp_migrate::{PostCopyDecision, PreCopyDecision, PreCopyOutcome, PreCopyReport};

        let stop_report = PreCopyReport {
            rounds: 5,
            final_dirty_bytes: 1,
            dirty_rate_pct_of_bandwidth: 85,
            logs: Vec::new(),
        };
        let stop = PreCopyOutcome::StopAndCheckpoint(stop_report);
        assert!(
            doctor_migration_probe_warnings(
                true,
                &stop,
                PostCopyDecision::Timeout,
                "FullReExecute"
            )
            .is_empty()
        );

        let converged_report = PreCopyReport {
            rounds: 1,
            final_dirty_bytes: 0,
            dirty_rate_pct_of_bandwidth: 10,
            logs: vec![fcp_migrate::PreCopyRoundLog {
                round_idx: 1,
                dirty_pages_this_round: 0,
                bandwidth_estimate_bytes_per_second: 100,
                dirty_rate_bytes_per_second: 10,
                dirty_rate_pct_of_bandwidth: 10,
                remaining_dirty_bytes: 0,
                decision: PreCopyDecision::Converged,
            }],
        };
        let converged = PreCopyOutcome::Converged(converged_report);
        assert_eq!(
            doctor_migration_probe_warnings(false, &converged, PostCopyDecision::Forwarded, "None"),
            vec![
                "soft_dirty_unavailable_uses_page_walker_fallback",
                "precopy_threshold_policy_not_triggered",
                "postcopy_timeout_policy_not_triggered",
                "postcopy_timeout_fallback_not_full_reexecute"
            ]
        );
    }

    #[test]
    fn doctor_all_includes_local_diagnosis() {
        // Mock host with a degraded connector so diagnosis engine produces fix-it recipes.
        let degraded_health = serde_json::to_value(ConnectorHealth::Degraded {
            reason: "Connection refused to api.github.com".to_owned(),
        })
        .expect("health should serialize");
        let connector = json!({
            "id": "fcp.github:enterprise:v1",
            "name": "GitHub Enterprise",
            "description": "GitHub connector.",
            "version": "1.2.3",
            "categories": ["code"],
            "tool_count": 2,
            "max_safety_tier": "risky",
            "enabled": true,
            "health": degraded_health,
            "last_health_check": "2026-03-10T00:00:00Z",
        });
        let (host, server) = spawn_mock_host(
            StdBTreeMap::from([
                (
                    "POST /rpc/discover".to_owned(),
                    mock_discovery_response_with_connectors(vec![connector]),
                ),
                ("POST /doctor".to_owned(), mock_doctor_report_json()),
            ]),
            2,
        );
        let (exit_code, payload) = execute_json(&[
            "fwc", "--json", "--host", &host, "doctor", "--zone", "z:work", "--all",
        ]);

        server.join().expect("mock host thread should complete");
        assert_eq!(exit_code, CliExitCode::Success.into());
        assert_eq!(payload["command"], "doctor");
        // Diagnosis section should exist with reports
        let reports = &payload["diagnosis"]["reports"];
        assert!(reports.is_array(), "diagnosis.reports should be an array");
        assert!(
            !reports.as_array().unwrap().is_empty(),
            "should have at least one report"
        );
        let first = &reports[0];
        assert_eq!(first["connector_id"], "fcp.github:enterprise:v1");
        // Degraded connector with "Connection refused" should produce a Network diagnosis.
        assert!(
            first["diagnoses"]
                .as_array()
                .unwrap()
                .iter()
                .any(|d| d["category"] == "network"),
            "expected network diagnosis for connection refused"
        );
    }

