    #[test]
    fn resumable_queue_item_includes_resume_command() {
        // Create a task and advance it to produce an execution history entry.
        // Then verify the task list includes the necessary information to
        // construct a resume command.
        let (create_exit, create_payload) = execute_json(&[
            "fwc",
            "--json",
            "task",
            "search for GitHub repositories matching 'fcp'",
        ]);
        assert_eq!(create_exit, CliExitCode::Success.into());

        let task_id = create_payload["task"]["id"]
            .as_str()
            .expect("task should have an id")
            .to_owned();

        // Resolve the task so it becomes ready for execution.
        let (resolve_exit, resolve_payload) = execute_json(&[
            "fwc", "--json", "task", "resolve", &task_id, "--until", "ready",
        ]);
        assert_eq!(resolve_exit, CliExitCode::Success.into());
        assert_eq!(resolve_payload["command"], "task");
        assert_eq!(resolve_payload["subcommand"], "resolve");
        assert!(
            resolve_payload["task"]["capsule_status"]
                .as_str()
                .is_some_and(|status| !status.is_empty()),
            "task resolve output should include capsule_status"
        );

        // List tasks and find the one we created.
        let (list_exit, list_payload) = execute_json(&["fwc", "--json", "task", "list"]);
        assert_eq!(list_exit, CliExitCode::Success.into());

        let tasks = list_payload["tasks"]
            .as_array()
            .expect("tasks should be an array");

        let our_task = tasks
            .iter()
            .find(|t| t["id"].as_str() == Some(task_id.as_str()));

        assert!(
            our_task.is_some(),
            "created task should appear in the task list"
        );

        let task_entry = our_task.expect("task must be found");
        // Each listed task should include enough info to construct a resume command:
        // - id: for `fwc task show <id>` / `fwc task run <id>`
        // - capsule_status: to know whether it's resumable
        assert!(
            task_entry["id"].as_str().is_some_and(|id| !id.is_empty()),
            "listed task should include id for resume"
        );
        assert!(
            task_entry["capsule_status"]
                .as_str()
                .is_some_and(|s| !s.is_empty()),
            "listed task should include capsule_status for resume decision"
        );
        // Verify the task is in a state that can be resumed/advanced.
        let resumable_states = [
            "ready-to-simulate",
            "ready-to-execute",
            "pending-question",
            "needs-answer",
            "new",
            "simulated",
        ];
        let current_status = task_entry["capsule_status"].as_str().unwrap_or("unknown");
        assert!(
            resumable_states.iter().any(|s| current_status.contains(s))
                || current_status.contains("ready"),
            "task status `{current_status}` should be a resumable state"
        );
    }

    // ── Seed helper for replay/compare/undo tests ───────────────────────

    fn seed_history_entries() -> (TempDir, Vec<String>, super::HistoryPathOverrideGuard) {
        let root = TempDir::new().expect("history tempdir should exist");
        let history_path = root.path().join("history.jsonl");
        let guard = super::install_test_history_path(history_path);

        // Entry 1: successful github create_issue
        super::append_history_entry(
            super::history::OpStatus::Success,
            "fcp.github",
            "github.create_issue",
            Some("z:work"),
            &json!({"owner":"octocat","repo":"hello-world","title":"test issue"}),
            Some(&json!({"ok":true,"issue":{"number":42}})),
            None,
            Some("idemp-replay-1"),
            25,
        )
        .expect("history append should succeed");

        // Entry 2: denied discord delete_message
        super::append_history_entry(
            super::history::OpStatus::Denied,
            "fcp.discord",
            "discord.delete_message",
            Some("z:work"),
            &json!({"channel_id":"123","message_id":"456"}),
            Some(&json!({"allowed":false})),
            Some("policy-denied".to_owned()),
            None,
            0,
        )
        .expect("history append should succeed");

        // Entry 3: simulated slack post_message
        super::append_history_entry(
            super::history::OpStatus::Simulated,
            "fcp.slack",
            "slack.post_message",
            Some("z:staging"),
            &json!({"channel":"C123","text":"hello from test"}),
            Some(&json!({"ok":true,"ts":"1234567890.123456"})),
            None,
            None,
            10,
        )
        .expect("history append should succeed");

        // Collect entry IDs from the store.
        let store = super::cli_history_store().expect("store should open");
        let mut filter = super::history::HistoryFilter::new();
        filter.limit = 100;
        let entries = store.query(&filter).expect("query should succeed");
        // Entries are returned reverse chronological, so index 0 is newest.
        let ids: Vec<String> = entries.iter().rev().map(|e| e.entry_id.clone()).collect();

        (root, ids, guard)
    }

